maritimeAIS
| where IngestionTime > ago(15m)
| summarize eventCount=count() by ShipName, timeBin=bin(IngestionTime, 1m)
| order by ShipName, timeBin asc

maritimeAIS
| count




// This KQL query was generated by AI:
// over the last 15 minuts are there any list the ships who emitted more than 1 event
//
maritimeAIS
| where IngestionTime > ago(15m)
| summarize eventCount=count() by ShipName
| where eventCount > 1
| order by eventCount desc, ShipName asc





// This KQL query was generated by AI:
// for eveents with shipanem I also want to know their location
//
maritimeAIS
| where IngestionTime > ago(20m)
| where isnotempty(ShipName)
| extend MinuteBin = bin(IngestionTime, 1m)
| summarize eventCount=count(), Latitudes=make_list(Latitude), Longitudes=make_list(Longitude) by ShipName, MinuteBin
| where eventCount > 1
| order by ShipName asc, MinuteBin asc

maritimeAIS
| where ShipName == 'CONSTITUTION'


.create materialized-view with (backfill=true) LatestShipPositions on table maritimeAIS
{
    maritimeAIS
    | extend CurrentLocation = pack("type", "Point", "coordinates", pack_array(Longitude, Latitude))
    | summarize arg_max(IngestionTime, *) by MMSI
}

.create-or-alter function with (docstring = "Dynamically maps vessels to current zones") vessels_in_zones() {
    maritimeAIS
    // Perform a cross-join/lookup to evaluate coordinates against zones
    | lookup kind=leftouter maritimezones on $left.DummyJoinKey == $right.DummyJoinKey
    // Evaluate if the vessel point is inside the zone polygon
    | extend IsInside = geo_point_in_polygon(todouble(Longitude), todouble(Latitude), ZonePolygonGeoJSON)
    | where IsInside == true
    | project MMSI, ZoneID
}


.alter-merge table maritimezones (
    ZoneID: string, 
    ZoneName: string, 
    RiskLevel: string, 
    PremiumMultiplier: decimal, 
    ZonePolygonGeoJSON: dynamic
)

maritimezones
| project ZoneID, ZoneName, RiskLevel, PremiumMultiplier, 
          // Explicitly parse the string column back into a dynamic GeoJSON object
          GeoJsonShape = parse_json(ZonePolygonGeoJSON)
| take 10


// 1. Get your real-time vessel telemetry stream
maritimeAIS 
// 1. Create a temporary matching key on the left table
| extend DummyJoinKey = 1
// 2. Create the same matching key on the right table inline during the lookup
| lookup kind=leftouter (
    maritimezones 
    | extend DummyJoinKey = 1
) on DummyJoinKey
// 3. Convert the stringified column to a dynamic object inside the geospatial math function
| extend IsInside = geo_point_in_polygon(
    todouble(Longitude), 
    todouble(Latitude), 
    parse_json(ZonePolygonGeoJSON)
)
// 4. Only keep rows where a vessel actually intersects a boundary
| where IsInside == true
| project-away DummyJoinKey
| where IngestionTime >= ago(1m)
| project MMSI, ShipName, ZoneName, RiskLevel, PremiumMultiplier, IngestionTime



.create-or-alter function GetLiveShipPositions() {
    union 
        (LatestShipPositions), 
        (maritimeAIS | where IngestionTime > ago(2m))
    | summarize arg_max(IngestionTime, *) by MMSI
    | project Latitude, Longitude, ShipName, SpeedKnots, IngestionTime, MMSI
}


